package com.dy.artisan3d.ui.screen.main.aboutimport androidx.compose.foundation.layout.PaddingValuesimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.foundation.lazy.itemsimport androidx.compose.material3.Scaffoldimport androidx.compose.runtime.Composableimport androidx.compose.runtime.collectAsStateimport androidx.compose.ui.Modifierimport androidx.compose.ui.unit.dpimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.app_nameimport com.dy.artisan3d.ui.component.ArtisanAboutCardimport com.dy.artisan3d.ui.component.Topbarimport org.jetbrains.compose.resources.stringResource@Composablefun AboutContent(    viewModel: AboutViewModel){    val state = viewModel.uiState.collectAsState()    Scaffold(        topBar = {            Topbar(title = stringResource(Res.string.app_name))        }    ){paddingValues ->        LazyColumn(modifier = Modifier.fillMaxSize().padding(paddingValues),            contentPadding = PaddingValues(top = 16.dp, start = 16.dp, end = 16.dp, bottom = 90.dp)){            items(state.value.aboutData){data->                ArtisanAboutCard(artisan = data)            }        }    }}